import json
import os
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel
import mlflow
import mlflow.sklearn
import mlflow.client
import numpy as np

# Set MLflow tracking URI
mlflow.set_tracking_uri("http://127.0.0.1:5000")

# FastAPI app
app = FastAPI()

# Global variables for the loaded model info
_model = None
_model_name = "breast-cancer-classifier"
_model_version = 1
_model_stage = "Production"
_model_type = ""

def get_model_info_from_registry():
    """Fetch model type information from MLflow Model Registry"""
    client = mlflow.client.MlflowClient()
    # Get the latest version in Production stage or version 1
    mv = client.get_model_version(name="breast-cancer-classifier", version=1)
    if hasattr(mv, 'run_id') and mv.run_id:
        run = client.get_run(mv.run_id)
        model_type = run.data.params.get("model_type", "unknown")
        return model_type
    return "unknown"

@app.on_event("startup")
def load_model_at_startup():
    """Load the registered model from MLflow Model Registry at startup."""
    global _model, _model_name, _model_version, _model_stage, _model_type
    # Load model from MLflow Model Registry
    model_uri = "models:/breast-cancer-classifier/1"
    _model = mlflow.sklearn.load_model(model_uri)
    _model_name = "breast-cancer-classifier"
    _model_version = 1
    _model_stage = "Production"
    # Get model_type from the run that created the model
    client = mlflow.client.MlflowClient()
    mv = client.get_model_version(name="breast-cancer-classifier", version=1)
    if hasattr(mv, 'run_id') and mv.run_id:
        run = client.get_run(mv.run_id)
        _model_type = run.data.params.get("model_type", "unknown")
    else:
        _model_type = "unknown"

class PredictRequest(BaseModel):
    features: list

class PredictBatchRequest(BaseModel):
    samples: list[list]

@app.get("/health")
def health_check():
    return {
        "status": "healthy",
        "model_loaded": _model is not None,
        "mlflow_tracking_uri": "http://127.0.0.1:5000"
    }

@app.get("/model-info")
def get_model_info():
    return {
        "model_name": _model_name,
        "model_version": _model_version,
        "model_stage": _model_stage,
        "model_type": _model_type
    }

@app.post("/predict")
def predict(request: PredictRequest):
    if len(request.features) != 30:
        raise HTTPException(status_code=400, detail="features must contain exactly 30 values")
    # Prepare input as a 2D array with one sample
    X = np.array([request.features]).reshape(1, -1)
    prediction = _model.predict(X)[0]
    prediction_label = "malignant" if prediction == 0 else "benign"
    return {
        "prediction": prediction,
        "prediction_label": prediction_label,
        "model_name": _model_name,
        "model_version": _model_version
    }

@app.post("/predict-batch")
def predict_batch(request: PredictBatchRequest):
    if not request.samples:
        raise HTTPException(status_code=422, detail="samples list is empty")
    for sample in request.samples:
        if len(sample) != 30:
            raise HTTPException(status_code=400, detail="each sample must have exactly 30 features")
    predictions = []
    for sample in request.samples:
        X = np.array([sample]).reshape(1, -1)
        pred = _model.predict(X)[0]
        prediction_label = "malignant" if pred == 0 else "benign"
        predictions.append({
            "prediction": pred,
            "prediction_label": prediction_label
        })
    return {
        "predictions": predictions,
        "count": len(request.samples),
        "model_name": _model_name,
        "model_version": _model_version
    }
EOF"}
